const struct sw_desc *sw_desc_for_game(u8 game_id)
{
	unsigned i;

	for (i = 0; i < sizeof(sw_descs) / sizeof(sw_descs[0]); i++) {
		if (sw_descs[i].game_id == game_id) return &sw_descs[i];
	}
	return NULL;
}
